/** Delegates to bfd_CaseUtils.mandatoryTasksComplete(). */
(function execute(inputs, outputs) {
    outputs.complete = new bfd_FlowSupport().mandatoryTasksComplete(inputs.caseSysId) ? 'true' : 'false';
})(inputs, outputs);

